svg.script:
(function() {
  var eyeball = document.getElementById('eyeball');
  var svg = document.querySelector('svg');

  // Eye socket center in SVG coordinates (computed from outer circle transform)
  var eyeCX = 170.730;
  var eyeCY = 27.364;

  // Max distance the pupil center can travel from eye center
  // = outer_radius - inner_radius = 15.8545 - 10.3521
  var maxTravel = 5.5;

  // Inner circle's matrix rotation components
  var a = -0.965926, b = -0.258819, c = -0.258819, d = 0.965926;
  // Inner circle's local cx/cy
  var pcx = 10.3521, pcy = 10.3521;
  // Precompute: offset from translation to actual center
  var ox = a * pcx + c * pcy; // ≈ -12.679
  var oy = b * pcx + d * pcy; // ≈  7.320

  function moveEye(svgX, svgY) {
    var dx = svgX - eyeCX;
    var dy = svgY - eyeCY;
    var dist = Math.sqrt(dx * dx + dy * dy);

    var tx, ty;
    if (dist === 0) {
      tx = eyeCX;
      ty = eyeCY;
    } else {
      var clamped = Math.min(dist, maxTravel);
      tx = eyeCX + (dx / dist) * clamped;
      ty = eyeCY + (dy / dist) * clamped;
    }

    var newE = tx - ox;
    var newF = ty - oy;
    eyeball.setAttribute('transform',
      'matrix(' + a + ' ' + b + ' ' + c + ' ' + d + ' ' + newE + ' ' + newF + ')');
  }

  function toSVG(clientX, clientY) {
    var pt = svg.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  svg.addEventListener('mousemove', function(e) {
    var p = toSVG(e.clientX, e.clientY);
    moveEye(p.x, p.y);
  });

  svg.addEventListener('mouseleave', function() {
    moveEye(eyeCX, eyeCY);
  });
})();
